public interface Shape {
    double calculateArea();
}

public double sum() {
    double totalArea = 0;

    for (Object shape : shapes) {
        if (shape instanceof Shape) {
            totalArea += ((Shape) shape).calculateArea();
        }
    }

    return totalArea;
}

